# >>> STATIC
_static_dig_action() {
    cat <<-'ARGCEOF'
	queries	Show now running queries (from system.processes)
	last-queries	Show last running queries (from system.query_log)
	slow-queries	Show slow (slower then 1 second, ordered by duration) queries (from system.query_log)
	query-patterns	Show queries grouped by normalized_query_hash with duration distribution (from system.query_log)
	merges	Show merges for MergeTree engine (system.merges)
	s3-queue	Show S3 Queue (system.s3queue_metadata_cache)
	azure-queue	Show Azure Queue (system.azure_queue_metadata_cache)
	mutations	Show mutations for MergeTree engine (system.mutations)
	replication-queue	Show replication queue for ReplicatedMergeTree engine (system.replication_queue)
	replicated-fetches	Show fetches for ReplicatedMergeTree engine (system.replicated_fetches)
	replicas	Show information about replicas (system.replicas)
	zookeeper	Browse ZooKeeper nodes (system.zookeeper)
	tables	Tables
	errors	Show all errors that happened in a server since start (system.errors)
	error-log	Show errors over time (system.error_log)
	backups	Show information about backups (system.backups)
	dictionaries	Show information about dictionaries (system.dictionaries)
	server-logs	Show server logs (system.text_log)
	loggers	Show loggers (system.text_log)
	background-schedule-pool	Show background schedule pool tasks (system.background_schedule_pool)
	background-schedule-pool-log	Show background schedule pool logs (system.background_schedule_pool_log)
	table-parts	Show table parts (system.parts)
	asynchronous-inserts	Show asynchronous inserts (system.asynchronous_inserts)
	asynchronous-insert-log	Show asynchronous insert log (system.asynchronous_insert_log)
	part-log	Show part log (system.part_log)
	metric-log	Show metrics with average per-second rates (system.metric_log)
	asynchronous-metric-log	Show asynchronous metrics with average values (system.asynchronous_metric_log)
	cpu-flamegraph	Show server CPU flamegraph (system.trace_log)
	real-flamegraph	Show server real (wall-clock) flamegraph (system.trace_log)
	memory-flamegraph	Show server memory flamegraph (system.trace_log)
	memory-sample-flamegraph	Show server memory sample flamegraph (system.trace_log)
	jemalloc-sample-flamegraph	Show server jemalloc sample flamegraph (system.trace_log)
	memory-allocated-without-check-flamegraph	Show server MemoryAllocatedWithoutCheck flamegraph (system.trace_log)
	events-flamegraph	Show server profile events flamegraph (system.trace_log)
	live-flamegraph	Show server live flamegraph (system.stack_trace)
	jemalloc-flamegraph	Show server jemalloc heap flamegraph
	client	Spawn client inside chdig
	export	Export data in various formats
ARGCEOF
}

_static_benchmark_queries_format() {
    cat <<-'ARGCEOF'
	tsv	one tab-escaped query per line
	script	parse the input as a script of multiple queries separated by semicolons
ARGCEOF
}

_static_benchmark_confidence() {
    cat <<-'ARGCEOF'
	0	80%
	1	90%
	2	95%
	3	98%
	4	99%
	5	99.5%(default)
ARGCEOF
}
