# >>> CHOICES
_choice_clickhouse_format() {
    clickhouse local --query "SELECT name FROM system.formats ORDER BY name" 2>/dev/null
}

_choice_clickhouse_progress() {
    printf '%s\n' tty on 1 true yes err off 0 false no
}
